      "rationale": "Blend feasible and optimistic residual completion estimates. Neighborhood capacity measures exclusion cost, while residual edges can distinguish joins whose neighborhoods have identical edge counts."
    },
    {
      "name": "include_exclude_bounds",
      "features": [
        {"name":"neighbor_edges","expression":{"op":"count","args":[{"op":"induced_edges","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}]}},
