        {"name":"residual_greedy","expression":{"op":"greedy_independent_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"residual_cover","expression":{"op":"clique_cover_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"neighbor_greedy","expression":{"op":"greedy_independent_weight","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}},
        {"name":"neighbor_cover","expression":{"op":"clique_cover_weight","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}}
      ],
      "rule": "weight + 0.7*residual_greedy + 0.3*residual_cover - 0.06*neighbor_greedy - 0.02*neighbor_cover + 0.1*neighbor_product/max(1e-9,abs(1+conflict_weight*conflict_weight)) - 0.1*residual_product/max(1e-9,abs(1+compatible_weight*compatible_weight))",
      "rationale": "Use weighted edge products to emphasize conflicts between valuable actions. These reduce to edge counts in the supplied unit examples, while neighborhood and residual packing summaries provide additional distinctions."
    },
    {
      "name": "gap_density_adaptive",
      "features": [
        {"name":"neighbor_edges","expression":{"op":"count","args":[{"op":"induced_edges","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"residual_edges","expression":{"op":"count","args":[{"op":"induced_edges","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}]}},
        {"name":"residual_greedy","expression":{"op":"greedy_independent_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"residual_cover","expression":{"op":"clique_cover_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"neighbor_greedy","expression":{"op":"greedy_independent_weight","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}},
        {"name":"total_edges","expression":{"op":"count","args":[{"op":"induced_edges","args":[{"op":"available","args":[]}]}]}}
      ],
      "rule": "weight + (0.65*residual_greedy + 0.35*residual_cover if station_gap+satellite_gap>0 else 0.9*residual_greedy + 0.1*residual_cover) - 0.04*neighbor_greedy + (0.02 if degree*2>remaining_count else 0.005)*neighbor_edges/max(1e-9,abs(1+degree)) - 0.02*residual_edges/max(1e-9,abs(1+total_edges))",
      "rationale": "Test stronger optimism under positive separation constraints and stronger neighborhood compression rewards for dense actions. Global edge count supplies inexpensive context, and every structural feature remains active in both regimes."
    },
    {
      "name": "completion_opportunity_ratio",
      "features": [
        {"name":"neighbor_edges","expression":{"op":"count","args":[{"op":"induced_edges","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"residual_edges","expression":{"op":"count","args":[{"op":"induced_edges","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}]}},
        {"name":"neighbor_greedy","expression":{"op":"greedy_independent_weight","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}},
        {"name":"neighbor_cover","expression":{"op":"clique_cover_weight","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}},
        {"name":"residual_greedy_loss","expression":{"op":"sub","args":[{"op":"sum_weights","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]},{"op":"greedy_independent_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}]}},
        {"name":"residual_cover_loss","expression":{"op":"sub","args":[{"op":"sum_weights","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]},{"op":"clique_cover_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}]}}
      ],
      "rule": "(weight + compatible_weight - residual_greedy_loss)/max(1e-9,abs(weight + 0.7*neighbor_greedy + 0.3*neighbor_cover)) + 0.15*(compatible_weight-residual_cover_loss)/max(1e-9,abs(1+remaining_count)) + 0.005*neighbor_edges/max(1e-9,abs(1+degree)) - 0.005*residual_edges/max(1e-9,abs(1+compatible_weight))",
      "rationale": "Rank estimated completion reward relative to displaced independent capacity. Residual packing losses retain global structural information, though the ratio may favor cheap exclusions too strongly."
    },
    {
      "name": "packing_sensitivity",
      "features": [
        {"name":"neighbor_edges","expression":{"op":"count","args":[{"op":"induced_edges","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"residual_edges","expression":{"op":"count","args":[{"op":"induced_edges","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}]}},
        {"name":"residual_greedy","expression":{"op":"greedy_independent_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"residual_cover","expression":{"op":"clique_cover_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"exclude_greedy","expression":{"op":"greedy_independent_weight","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}},
