      ],
      "rule": "weight + residual_greedy + 0.25*(residual_cover-residual_greedy) + 0.3*(weight+residual_greedy-exclude_greedy) - 0.03*closed_greedy - 0.005*residual_edges/max(1e-9,abs(1+compatible_weight)) + 0.003*neighbor_edges/max(1e-9,abs(1+degree))",
      "rationale": "Reward candidates whose forced completion improves on packing after deletion. Closed-neighborhood packing adds a local replacement signal, with edge summaries addressing externally different equality joins."
    },
    {
      "name": "edge_removal_efficiency",
      "features": [
        {"name":"neighbor_edges","expression":{"op":"count","args":[{"op":"induced_edges","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"residual_edges","expression":{"op":"count","args":[{"op":"induced_edges","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}]}},
        {"name":"residual_greedy","expression":{"op":"greedy_independent_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"residual_cover","expression":{"op":"clique_cover_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}},
        {"name":"removed_min","expression":{"op":"sub","args":[{"op":"edge_min_weight_sum","args":[{"op":"induced_edges","args":[{"op":"available","args":[]}]}]},{"op":"edge_min_weight_sum","args":[{"op":"induced_edges","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}]}]}},
        {"name":"exclude_cover","expression":{"op":"clique_cover_weight","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}}
      ],
      "rule": "weight + 0.55*residual_greedy + 0.45*residual_cover + 0.12*removed_min/max(1e-9,abs(weight+conflict_weight)) - 0.15*exclude_cover + 0.006*neighbor_edges/max(1e-9,abs(1+degree)) - 0.006*residual_edges/max(1e-9,abs(1+compatible_weight))",
      "rationale": "Combine completion potential with weighted conflicts eliminated per blocked reward. The deletion cover estimates competing potential; removal efficiency may help under dense constraints but remains a heuristic."
    }
  ]
}
